    scope:recipient = {
        lyd_c2_elector_trigger = yes
        faith = { religion = religion:confucianism_religion any_faith_rite = { count >= 1 } NOT = { any_faith_rite = { NOT = { lyd_c2_receiver_free_trigger = yes } } } }
        faith != scope:actor.faith
        rite = faith.main_rite
        rite = { lyd_c2_receiver_free_trigger = yes }
    }
}

lyd_c2_start_detach_trigger.definition:
lyd_c2_start_detach_trigger = {
    lyd_c2_actor_trigger = yes
    NOT = { has_variable = lyd_c2_active }
    NOT = { rite = faith.main_rite }
    rite = { lyd_c2_school_free_trigger = yes }
}

lyd_c2_cancel_proposal_decision.definition:
lyd_c2_cancel_proposal_decision = {
    picture = { reference = "gfx/interface/illustrations/decisions/decision_personal_religious.dds" }
    decision_group_type = religious
    ai_check_interval = 0
    desc = lyd_c2_cancel_proposal_decision_desc
    selection_tooltip = lyd_c2_cancel_proposal_decision_tooltip
    confirm_text = lyd_c2_cancel_proposal_decision_confirm
    is_shown = { is_ai = no has_variable = lyd_c2_active }
    is_valid = {
        custom_description = {
            text = lyd_c2_cancel_requirements_tt
            is_ai = no has_variable = lyd_c2_active
        }
    }
    effect = {
        custom_tooltip = lyd_c2_cancel_round_tt
        hidden_effect = { lyd_c2_cancel_round_effect = yes }
    }
    ai_will_do = { base = 0 }
}

lyd_c2_propose_join_interaction.definition:
lyd_c2_propose_join_interaction = {
    category = interaction_category_religion
    common_interaction = yes
    desc = lyd_c2_propose_join_interaction_desc
    # Automatic delivery is not approval: all voters and representatives receive
    # separate affirmative/refusal options after this player opens the round.
    auto_accept = yes
    is_shown = {
        scope:actor = { lyd_c2_actor_trigger = yes }
        scope:recipient = { is_alive = yes faith != scope:actor.faith faith = { religion = religion:confucianism_religion } }
    }
    is_valid_showing_failures_only = {
        custom_description = {
            text = lyd_c2_join_requirements_tt
            lyd_c2_start_join_trigger = yes
        }
    }
    on_auto_accept = {
        custom_tooltip = lyd_c2_join_open_tt
        hidden_effect = { lyd_c2_begin_join_effect = yes }
    }
    ai_will_do = { base = 0 }
}

lyd_c2_start_round_effect.definition:
lyd_c2_start_round_effect = {
    if = {
    limit = { lyd_c2_actor_trigger = yes is_ai = no }
    # Character scope, set by the already guarded join/detach entry.
    save_scope_as = lyd_c2_actor
    lyd_c2_reset_round_effect = yes
    set_variable = { name = lyd_c2_active value = 1 days = 365 }
    set_variable = { name = lyd_c2_kind value = $KIND$ }
    set_variable = { name = lyd_c2_terms_revision value = 1 }
    set_variable = { name = lyd_c2_result value = 0 }
    # Persistent per-actor generation: rite serials alone can collide after the
    # same player changes school. Never include this in reset_round fields.
    if = { limit = { NOT = { has_variable = lyd_c2_callback_nonce } } set_variable = { name = lyd_c2_callback_nonce value = 0 } }
    change_variable = { name = lyd_c2_callback_nonce add = 1 }
    if = { limit = { NOT = { has_variable = lyd_c2_completed_joins } } set_variable = { name = lyd_c2_completed_joins value = 0 } }
    if = { limit = { NOT = { has_variable = lyd_c2_completed_detaches } } set_variable = { name = lyd_c2_completed_detaches value = 0 } }
    set_variable = { name = lyd_c2_source_faith value = faith }
    set_variable = { name = lyd_c2_source_main value = faith.main_rite }
    set_variable = { name = lyd_c2_moving_rite value = rite }
    set_variable = { name = lyd_c2_source_singleton value = 0 }
    if = { limit = { faith = { lyd_c2_single_rite_faith_trigger = yes } }
        set_variable = { name = lyd_c2_source_singleton value = 1 }
    }
    if = { limit = { exists = rite.head_of_rite } set_variable = { name = lyd_c2_source_rite_head value = rite.head_of_rite } }
    if = { limit = { exists = faith.religious_head }
        set_variable = { name = lyd_c2_source_head value = faith.religious_head }
        set_variable = { name = lyd_c2_source_head_title value = faith.religious_head_title }
        faith.religious_head = {
            every_held_title = {
                limit = { this != scope:lyd_c2_actor.var:lyd_c2_source_head_title }
                save_scope_as = lyd_c2_protected_title
                scope:lyd_c2_actor = { add_to_variable_list = { name = lyd_c2_protected_head_titles target = scope:lyd_c2_protected_title } }
            }
        }
    }
    rite = {
        save_scope_as = lyd_c2_event_school
        if = { limit = { NOT = { has_variable = lyd_c2_proposal_serial } } set_variable = { name = lyd_c2_proposal_serial value = 0 } }
        change_variable = { name = lyd_c2_proposal_serial add = 1 }
        set_variable = { name = lyd_c2_lock_serial value = var:lyd_c2_proposal_serial }
        set_variable = { name = lyd_c2_proposal_owner value = scope:lyd_c2_actor days = 365 }
        scope:lyd_c2_actor = { set_variable = { name = lyd_c2_serial value = prev.var:lyd_c2_proposal_serial } }
    }
    # Tooltip projection does not execute the preceding assignments.
    # Read and deliver this round only after its actual variables exist.
    if = {
        limit = {
            has_variable = lyd_c2_active
            has_variable = lyd_c2_serial
            has_variable = lyd_c2_terms_revision
            has_variable = lyd_c2_callback_nonce
            has_variable = lyd_c2_kind
            has_variable = lyd_c2_source_faith
            has_variable = lyd_c2_source_main
            has_variable = lyd_c2_moving_rite
        }
        save_scope_value_as = { name = lyd_c2_event_serial value = var:lyd_c2_serial }
        save_scope_value_as = { name = lyd_c2_event_terms value = var:lyd_c2_terms_revision }
        save_scope_value_as = { name = lyd_c2_event_nonce value = var:lyd_c2_callback_nonce }
        set_variable = { name = lyd_c2_source_total value = 0 }
        set_variable = { name = lyd_c2_target_total value = 0 }
        set_variable = { name = lyd_c2_target_rite_total value = 0 }
        set_variable = { name = lyd_c2_dormant_total value = 0 }
        set_variable = { name = lyd_c2_source_yes value = 0 }
        set_variable = { name = lyd_c2_target_yes value = 0 }
        set_variable = { name = lyd_c2_player_total value = 0 }
        set_variable = { name = lyd_c2_player_yes value = 0 }
        if = {
            limit = { var:lyd_c2_kind = 1 }
            set_variable = { name = lyd_c2_target_rep value = scope:recipient }
            set_variable = { name = lyd_c2_target_faith value = scope:recipient.faith }
            set_variable = { name = lyd_c2_target_main value = scope:recipient.faith.main_rite }
            if = {
                limit = { exists = scope:recipient.faith.religious_head }
                set_variable = { name = lyd_c2_target_head value = scope:recipient.faith.religious_head }
            }
            lyd_c2_collect_target_effect = yes
        }
        lyd_c2_collect_source_effect = yes
        lyd_c2_snapshot_terms_effect = yes
        trigger_event = lyd.200
        trigger_event = { id = lyd.229 days = 365 }
    }
    }
}

lyd_c2_reject_round_effect.definition:
lyd_c2_reject_round_effect = {
    if = {
        limit = { lyd_c2_current_proposal_trigger = { ACTOR = scope:lyd_c2_actor } }
        var:lyd_c2_moving_rite = { set_variable = { name = lyd_c2_retry_cooldown value = 1 days = 365 } }
        set_variable = { name = lyd_c2_result value = 2 }
        lyd_c2_release_locks_effect = yes
        trigger_event = lyd.228
    }
}

lyd_c2_cancel_round_effect.definition:
lyd_c2_cancel_round_effect = {
    if = {
        limit = { is_ai = no has_variable = lyd_c2_active }
        set_variable = { name = lyd_c2_result value = 3 }
        lyd_c2_release_locks_effect = yes
        trigger_event = lyd.228
    }
}

lyd_c2_expire_round_effect.definition:
lyd_c2_expire_round_effect = {
    if = {
        # Expiry may clean an otherwise invalid snapshot; do not use the
        # current-proposal predicate, whose lock lifetime expires today.
        limit = {
            exists = scope:lyd_c2_actor
            exists = scope:lyd_c2_event_school
            this = scope:lyd_c2_actor
            var:lyd_c2_moving_rite = scope:lyd_c2_event_school
            var:lyd_c2_serial = scope:lyd_c2_event_serial
            var:lyd_c2_terms_revision = scope:lyd_c2_event_terms
            has_variable = lyd_c2_callback_nonce
            var:lyd_c2_callback_nonce = scope:lyd_c2_event_nonce
            var:lyd_c2_result = 0
        }
        set_variable = { name = lyd_c2_result value = 4 }
        lyd_c2_release_locks_effect = yes
        trigger_event = lyd.228
    }
}

lyd.228.definition:
lyd.228 = {
    type = character_event
    title = lyd_c2_result_t
    desc = {
        triggered_desc = { trigger = { var:lyd_c2_result = 1 } desc = lyd_c2_success_desc }
        triggered_desc = { trigger = { var:lyd_c2_result = 2 } desc = lyd_c2_rejected_desc }
        triggered_desc = { trigger = { var:lyd_c2_result = 3 } desc = lyd_c2_cancelled_desc }
        triggered_desc = { trigger = { var:lyd_c2_result = 4 } desc = lyd_c2_expired_desc }
        triggered_desc = { trigger = { var:lyd_c2_result = 5 } desc = lyd_c2_failed_desc }
    }
    theme = faith
    trigger = { is_ai = no has_variable = lyd_c2_result }
    option = { name = lyd_c2_acknowledge }
}

lyd.229.definition:
lyd.229 = {
    type = character_event
    hidden = yes
    immediate = { lyd_c2_expire_round_effect = yes }
}
